dtsPropsFor.Button:
/** Visual style. default = black fill (the yourpeer primary action); outline = white with dark border; secondary = neutral-100 fill; ghost = no fill until hover; link = underlined text; destructive = red fill. */
variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
/** Height: sm 32px, default 36px, lg 40px, icon 36x36 square. */
size?: "default" | "sm" | "lg" | "icon";
/** Render the child element (e.g. an <a>) with button styling instead of a <button>. */
asChild?: boolean;
className?: string;
disabled?: boolean;
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
children?: React.ReactNode;
/** Any native <button> attribute (onClick, type, disabled, aria-*) is forwarded. */
[attr: string]: unknown;

dtsPropsFor.Badge:
/** default = black pill text on dark; secondary = neutral-100; destructive = red; outline = bordered, transparent. */
variant?: "default" | "secondary" | "destructive" | "outline";
className?: string;
children?: React.ReactNode;

dtsPropsFor.Dialog:
/** Controlled open state. Omit (with DialogTrigger) for uncontrolled. */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
/** Compose: DialogTrigger, DialogContent > DialogHeader (DialogTitle, DialogDescription) + body + DialogFooter; DialogClose closes. */
children?: React.ReactNode;

dtsPropsFor.AlertDialog:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Compose: AlertDialogTrigger, AlertDialogContent > AlertDialogHeader (AlertDialogTitle, AlertDialogDescription) + AlertDialogFooter (AlertDialogCancel, AlertDialogAction). */
children?: React.ReactNode;

dtsPropsFor.DropdownMenu:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
/** Compose: DropdownMenuTrigger (asChild) + DropdownMenuContent > DropdownMenuLabel, DropdownMenuItem, DropdownMenuCheckboxItem, DropdownMenuRadioGroup/RadioItem, DropdownMenuSeparator, DropdownMenuSub. */
children?: React.ReactNode;

dtsPropsFor.Popover:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
/** Compose: PopoverTrigger (asChild) + PopoverContent (align, sideOffset, className). PopoverAnchor optional. */
children?: React.ReactNode;

dtsPropsFor.Command:
/** Filter value (controlled) for the built-in fuzzy filter. */
value?: string;
onValueChange?: (value: string) => void;
/** Disable cmdk's built-in filtering (when you filter yourself). */
shouldFilter?: boolean;
className?: string;
/** Compose: CommandInput, CommandList > CommandEmpty, CommandGroup (heading) > CommandItem (onSelect), CommandSeparator, CommandShortcut. CommandDialog wraps it in a Dialog. */
children?: React.ReactNode;

dtsPropsFor.MultiSelect:
/** Selectable options. */
options: { label: string; value: string }[];
/** Called with the full array of selected values on every change. */
onValueChange: (value: string[]) => void;
/** Values selected on mount. */
defaultValue?: string[];
/** Text shown when nothing is selected. Default "Select options". */
placeholder?: string;
/** Render the popover as modal (traps focus). Default false. */
modalPopover?: boolean;
variant?: "default" | "secondary" | "destructive" | "inverted";
className?: string;
disabled?: boolean;

dtsPropsFor.Separator:
orientation?: "horizontal" | "vertical";
/** true (default) hides it from assistive tech. */
decorative?: boolean;
className?: string;

dtsPropsFor.Skeleton:
/** Size and shape it with utilities, e.g. "h-4 w-40 rounded-full". */
className?: string;
style?: React.CSSProperties;

dtsPropsFor.TranslatableText:
/** English source string; rendered translated when the user picked another language. */
text: string;
/** Optional translation key when the same English text needs a distinct translation. */
id?: string;
className?: string;
expectTranslation?: boolean;
style?: Record<string, string>;

